from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, renderers, status
from .models import TenantAPIConfiguration
from .forms import TenantAPIConfigForm

class TenantConfigBrowsableEditView(APIView):
    permission_classes = [permissions.IsAuthenticated]
    renderer_classes = [renderers.JSONRenderer, renderers.BrowsableAPIRenderer]

    def get(self, request, pk):
        # Restrict lookup strictly to tenant configuration owned by user's tenant
        config = TenantAPIConfiguration.objects.filter(
            pk=pk,
            tenant=request.user.tenant
        ).first()
        if not config:
            return Response({"error": "Not found or access denied"}, status=status.HTTP_404_NOT_FOUND)

        if request.accepted_renderer.format == 'html':
            form = TenantAPIConfigForm(instance=config)
            return Response({"form": form.as_p(), "client_id": config.client_id})

        return Response({"client_id": config.client_id})
